create table if not exists public.guimmia_recovery_cases(id uuid primary key default gen_random_uuid(),case_id uuid not null references public.guimmia_brain_cases(id) on delete cascade,operating_agency_id uuid not null references public.guimmia_online_agency_profile(id),source_type text not null,source_id text not null,status text not null default 'DETECTED' check(status in('DETECTED','TRIAGED','RETRYING','COMPENSATING','RESOLVED','ESCALATED')),request_id text not null,idempotency_key text not null,payload_fingerprint text not null,attempt integer not null default 0 check(attempt>=0),max_attempts integer not null default 3 check(max_attempts>0),assigned_staff_id uuid references public.guimmia_internal_staff_members(id),compensation jsonb not null default '{}'::jsonb,approval_actor_type text check(approval_actor_type is null or approval_actor_type='HUMAN'),approved_by uuid,approved_at timestamptz,resolution_fingerprint text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(source_type,source_id,idempotency_key));
create table if not exists public.guimmia_customer_journey_profiles(id uuid primary key default gen_random_uuid(),case_id uuid not null unique references public.guimmia_brain_cases(id) on delete cascade,operating_agency_id uuid not null references public.guimmia_online_agency_profile(id),customer_contact_id uuid not null,party_role text not null check(party_role in('OWNER','LANDLORD','SELLER','BUYER','TENANT','GUEST','REPRESENTATIVE')),customer_intent text not null check(customer_intent in('SELL','BUY','RENT_OUT','RENT','SHORT_STAY')),customer_service_model text not null check(customer_service_model in('COMPLETA','MENSILE')),status text not null default 'INTAKE' check(status in('INTAKE','PROFILE_COMPLETE','SERVICE_SELECTED','ACTIVE','WAITING_CUSTOMER','WAITING_PROFESSIONAL','COMPLETED','CANCELLED')),locale text not null default 'it-IT',preferred_channel text not null check(preferred_channel in('EMAIL','SMS','PHONE','WHATSAPP','PORTAL','IN_APP')),service_scope_acknowledged boolean not null default false,fixed_compensation_disclosed boolean not null default false,physical_step_owner text not null check(physical_step_owner in('CUSTOMER','GUIMMIA','PROFESSIONAL')),internal_owner_id uuid references public.guimmia_internal_staff_members(id),onboarding_context jsonb not null default '{}'::jsonb,last_context_hash text,started_at timestamptz not null default now(),completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.guimmia_customer_visible_milestones(id uuid primary key default gen_random_uuid(),journey_id uuid not null references public.guimmia_customer_journey_profiles(id) on delete cascade,case_id uuid not null references public.guimmia_brain_cases(id) on delete cascade,code text not null,title text not null,category text not null,status text not null default 'PENDING' check(status in('PENDING','IN_PROGRESS','WAITING_CUSTOMER','WAITING_GUIMMIA','WAITING_PROFESSIONAL','COMPLETED','BLOCKED','CANCELLED')),sequence_no integer not null check(sequence_no>0),customer_message text,next_action text,due_at timestamptz,evidence jsonb not null default '[]'::jsonb,material boolean not null default false,human_approved_by uuid,human_approved_at timestamptz,visible boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(journey_id,code));
create table if not exists public.guimmia_customer_action_requests(id uuid primary key default gen_random_uuid(),journey_id uuid not null references public.guimmia_customer_journey_profiles(id) on delete cascade,case_id uuid not null references public.guimmia_brain_cases(id) on delete cascade,action_type text not null check(action_type in('UPLOAD_DOCUMENT','PROVIDE_INFORMATION','ACCEPT_SERVICE_SCOPE','REVIEW_LISTING','APPROVE_LISTING','CONFIRM_APPOINTMENT','REVIEW_DOCUMENT','APPROVE_DOCUMENT','ACCEPT_OFFER','COUNTEROFFER','CANDIDATE_SELECTION','CONTACT_GUIMMIA')),status text not null default 'OPEN' check(status in('OPEN','VIEWED','COMPLETED','DECLINED','EXPIRED','CANCELLED')),requested_by_actor_type text not null check(requested_by_actor_type in('HUMAN','SYSTEM','AI')),requested_by uuid,payload jsonb not null default '{}'::jsonb,customer_response jsonb not null default '{}'::jsonb,completed_by_actor_type text check(completed_by_actor_type is null or completed_by_actor_type in('CUSTOMER','HUMAN')),completed_by uuid,completed_at timestamptz,due_at timestamptz,idempotency_key text not null unique,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.guimmia_document_workspaces(id uuid primary key default gen_random_uuid(),case_id uuid not null references public.guimmia_brain_cases(id) on delete cascade,journey_id uuid not null references public.guimmia_customer_journey_profiles(id) on delete cascade,document_type text not null check(document_type in('RENTAL_CONTRACT','PURCHASE_PROPOSAL','PRELIMINARY','MANDATE','LISTING_DOCUMENT','OTHER')),status text not null default 'DRAFT' check(status in('DRAFT','INPUT_PENDING','PREPARED','HUMAN_REVIEW','CUSTOMER_REVIEW','APPROVED','SIGNED','ARCHIVED','CANCELLED')),version integer not null default 1 check(version>0),template_version text,inputs jsonb not null default '{}'::jsonb,dynamic_rulesets jsonb not null default '[]'::jsonb,content_hash text,prepared_by_actor_type text check(prepared_by_actor_type is null or prepared_by_actor_type in('HUMAN','SYSTEM','AI')),prepared_by uuid,professional_review_required boolean not null default false,professional_reviewed_by uuid,professional_reviewed_at timestamptz,human_approved_by uuid,human_approved_at timestamptz,customer_review_evidence jsonb not null default '{}'::jsonb,signature_evidence jsonb not null default '{}'::jsonb,signed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(case_id,document_type,version));
do $$ declare t text;begin foreach t in array array['guimmia_online_agency_profile','guimmia_internal_staff_members','guimmia_case_internal_assignments','guimmia_contact_channel_profiles','guimmia_communication_threads','guimmia_message_templates','guimmia_message_outbox','guimmia_professional_profiles','guimmia_professional_service_catalog','guimmia_agency_calendars','guimmia_appointment_types','guimmia_appointments','guimmia_professional_service_requests','guimmia_sla_policies','guimmia_agency_operational_tasks','guimmia_integration_connections','guimmia_customer_identity_profiles','guimmia_customer_mandates','guimmia_privacy_requests','guimmia_appointment_slot_holds','guimmia_voice_call_sessions','guimmia_recovery_cases','guimmia_customer_journey_profiles','guimmia_customer_visible_milestones','guimmia_customer_action_requests','guimmia_document_workspaces'] loop execute format('drop trigger if exists %I on public.%I','trg_'||t||'_updated_at',t);execute format('create trigger %I before update on public.%I for each row execute function public.guimmia_set_updated_at()','trg_'||t||'_updated_at',t);end loop;end $$;
do $$ declare t text;begin foreach t in array array['guimmia_online_agency_profile','guimmia_internal_staff_members','guimmia_case_internal_assignments','guimmia_contact_channel_profiles','guimmia_consent_records','guimmia_communication_threads','guimmia_communication_events','guimmia_message_templates','guimmia_message_outbox','guimmia_professional_profiles','guimmia_professional_service_catalog','guimmia_agency_calendars','guimmia_availability_rules','guimmia_appointment_types','guimmia_appointments','guimmia_appointment_events','guimmia_professional_service_requests','guimmia_professional_service_events','guimmia_sla_policies','guimmia_agency_operational_tasks','guimmia_agency_task_events','guimmia_agency_escalation_events','guimmia_integration_connections','guimmia_integration_delivery_events','guimmia_customer_identity_profiles','guimmia_customer_mandates','guimmia_privacy_requests','guimmia_appointment_slot_holds','guimmia_voice_call_sessions','guimmia_voice_call_events','guimmia_integration_webhook_inbox','guimmia_recovery_cases','guimmia_customer_journey_profiles','guimmia_customer_visible_milestones','guimmia_customer_action_requests','guimmia_document_workspaces'] loop execute format('alter table public.%I enable row level security',t);execute format('alter table public.%I force row level security',t);end loop;end $$;
